/**
 * Genera un mapa de Picos Afilados / Agujas (Shattered Peaks / Badlands Spikes)
 * Topografía: Columnas estrechas de gran altitud, crestas angulosas y cañones con estratificación mineral.
 * Implementación: Ruido Ridged-Multifractal (1.0 - |noise|) con corte exponencial.
 */
async function buildShatteredPeaks(originX = 0, originY = 0, originZ = 0, options = {}) {
    const mapWidth = options.mapWidth || 128;
    const mapHeight = options.mapHeight || 48;
    const mapDepth = options.mapDepth || 128;
    const seaLevel = options.seaLevel || 6;
    const snowLine = options.snowLine || 38;

    const rockMat = options.rockMat || 'roca';
    const stoneBrickMat = options.stoneBrickMat || 'ladrillo_piedra';
    const cobblestoneMat = options.cobblestoneMat || 'adoquin';
    const sandstoneMat = options.sandstoneMat || 'arenisca';
    const orangeMat = options.orangeMat || 'hormig-n-naranja';
    const redMat = options.redMat || 'red_concrete';
    const yellowMat = options.yellowMat || 'yellow';
    const valleyFloorMat = options.valleyFloorMat || 'arena';
    const waterMat = options.waterMat || 'agua';
    const snowMat = options.snowMat || 'nieve';
    const goldOreMat = options.goldOreMat || 'oro';
    const shrubMat = options.shrubMat || 'hierba-alta';
    const bedrockMat = options.bedrockMat || 'obsidiana';

    if (typeof game !== 'undefined' && game.addMaterial) {
        await Promise.all([
            game.addMaterial(rockMat).catch(() => null),
            game.addMaterial(stoneBrickMat).catch(() => null),
            game.addMaterial(cobblestoneMat).catch(() => null),
            game.addMaterial(sandstoneMat).catch(() => null),
            game.addMaterial(orangeMat).catch(() => null),
            game.addMaterial(redMat).catch(() => null),
            game.addMaterial(yellowMat).catch(() => null),
            game.addMaterial(valleyFloorMat).catch(() => null),
            game.addMaterial(waterMat).catch(() => null),
            game.addMaterial(snowMat).catch(() => null),
            game.addMaterial(goldOreMat).catch(() => null),
            game.addMaterial(shrubMat).catch(() => null),
            game.addMaterial(bedrockMat).catch(() => null)
        ]);
    }

    if (typeof beginBatch === 'function') beginBatch();

    function getHeight(x, z) {
        const fx = x * 0.045;
        const fz = z * 0.045;

        const ridge1 = 1.0 - Math.abs(Math.sin(fx) * Math.cos(fz));
        const ridge2 = 1.0 - Math.abs(Math.sin(fx * 2.3 + 1.2) * Math.sin(fz * 2.1 + 0.7));
        const ridge3 = 1.0 - Math.abs(Math.cos(fx * 4.4 - fz * 3.9));

        let combined = ridge1 * 0.62 + ridge2 * 0.28 + ridge3 * 0.10;
        combined = Math.pow(combined, 2.9);

        return Math.floor(4 + combined * (mapHeight - 7));
    }

    for (let x = 0; x < mapWidth; x++) {
        for (let z = 0; z < mapDepth; z++) {
            const surfaceY = getHeight(x, z);

            const hRight = getHeight(Math.min(x + 1, mapWidth - 1), z);
            const hForward = getHeight(x, Math.min(z + 1, mapDepth - 1));
            const slope = Math.abs(surfaceY - hRight) + Math.abs(surfaceY - hForward);

            for (let y = 0; y <= Math.max(surfaceY, seaLevel); y++) {
                const gx = originX + x;
                const gy = originY + y;
                const gz = originZ + z;

                if (y > surfaceY && y <= seaLevel) {
                    setVoxel(gx, gy, gz, waterMat);
                } else if (y <= surfaceY) {
                    let mat = rockMat;
                    const stratum = y % 14;

                    if (y >= snowLine && slope < 3) {
                        mat = snowMat;
                    } else if (y === surfaceY && y <= seaLevel + 1 && slope < 2) {
                        mat = valleyFloorMat;
                    } else if (stratum >= 0 && stratum <= 2) {
                        mat = orangeMat;
                    } else if (stratum === 3 || stratum === 4) {
                        mat = sandstoneMat;
                    } else if (stratum === 5 || stratum === 6) {
                        mat = redMat;
                    } else if (stratum === 7) {
                        mat = yellowMat;
                    } else if (stratum >= 8 && stratum <= 10) {
                        mat = (slope >= 4) ? cobblestoneMat : stoneBrickMat;
                    } else {
                        const isOre = (x * 13 + y * 7 + z * 31) % 43 === 0;
                        mat = isOre ? goldOreMat : ((y === 0) ? bedrockMat : rockMat);
                    }

                    setVoxel(gx, gy, gz, mat);
                }
            }

            const isValley = surfaceY <= seaLevel + 2 && slope < 2;
            if (isValley) {
                const rng = Math.abs(Math.sin(x * 12.9898 + z * 78.233)) * 43758.5453;
                const val = rng - Math.floor(rng);

                if (val < 0.035) {
                    setVoxel(originX + x, originY + surfaceY + 1, originZ + z, shrubMat);
                }
            }
        }
    }

    if (typeof endBatch === 'function') endBatch();
}

